import { useState } from "react";
import "./App.css";
import "./Map.css";
import { SearchBar } from "./components/SearchBar";
import { SearchResultsList } from "./components/SearchResultsList";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";

function App() {
  const [results, setResults] = useState([]);

  return (
    <div className="App">
      {/* Left column: Map */}
      <div className="map">
        <MapContainer center={[40.7128, -74.006]} zoom={12} style={{ height: "100%", width: "100%" }}>
          <TileLayer
            url="https://api.maptiler.com/maps/basic-v2/256/{z}/{x}/{y}.png?key=LK8ZxnWkzmRn4IQLymXU"
            attribution="&copy; OpenStreetMap contributors"
          />
          {results.map((result, idx) => (
            result.lat && result.lng && (
              <Marker key={idx} position={[result.lat, result.lng]}>
                <Popup>
                  <strong>{result.name}</strong><br />
                  {result.product_description}
                </Popup>
              </Marker>
            )
          ))}
        </MapContainer>
      </div>

      {/* Right column: Search UI */}
      <div className="right-column">
        <div className="search-bar-container">
          <SearchBar setResults={setResults} />
        </div>
        <div className="search-results-container">
          <SearchResultsList results={results} />
        </div>
      </div>
    </div>
  );
}

export default App;
